changeSet.sql:
DELETE FROM registration.cards WHERE type = 'DEBIT';
UPDATE registration.cards SET invoice_payment_day = 1 WHERE invoice_payment_day IS NULL;
ALTER TABLE registration.cards
    DROP CONSTRAINT cards_last_four_digits_type_key;
ALTER TABLE registration.cards
    DROP COLUMN type;
ALTER TABLE registration.cards
    ADD CONSTRAINT cards_last_four_digits_key UNIQUE (last_four_digits);
ALTER TABLE registration.cards
    ALTER COLUMN invoice_payment_day SET NOT NULL;

rollback.sql:
ALTER TABLE registration.cards
    ALTER COLUMN invoice_payment_day DROP NOT NULL;
ALTER TABLE registration.cards
    DROP CONSTRAINT cards_last_four_digits_key;
ALTER TABLE registration.cards
    ADD COLUMN type varchar(45) NOT NULL DEFAULT 'CREDIT';
ALTER TABLE registration.cards
    ALTER COLUMN type DROP DEFAULT;
ALTER TABLE registration.cards
    ADD CONSTRAINT cards_last_four_digits_type_key UNIQUE (last_four_digits, type);
